	/**
	 * Default Constructor
	 */
    public NoteService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new NoteEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(NoteRepository.class) );
		this.validator		= applicationContext.getBean(NoteValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Note
	 */
		public Note createNote( CreateNoteCommand command ) {

		Note entity = new Note();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setNoteId( command.getNoteId() );
            entity.setTitle( command.getTitle() );
            entity.setContent( command.getContent() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setUpdatedAt( command.getUpdatedAt() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Note {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateNoteCommand
	 * @return		Note
	 */
	public Note updateNote( UpdateNoteCommand command ) {

		Note entity = new Note();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setNoteId( command.getNoteId() );
            entity.setTitle( command.getTitle() );
            entity.setContent( command.getContent() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setUpdatedAt( command.getUpdatedAt() );
            entity.setOrganization( command.getOrganization() );
            entity.setOwner( command.getOwner() );
            entity.setAccount( command.getAccount() );
            entity.setContact( command.getContact() );
            entity.setOpportunity( command.getOpportunity() );
            entity.setCase( command.getCase() );
            entity.setLead( command.getLead() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Note {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteNoteCommand
	 */
	public void delete( DeleteNoteCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getNoteId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Note {0} ", id );

	}

	/**
	 * Method to retrieve the Note via NoteFetchOneSummary
	 * @param 	summary NoteFetchOneSummary
	 * @return 	NoteFetchOneResponse
	 */
	public Note getNote( NoteFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "NoteFetchOneSummary arg cannot be null" );

		Note entity = null;
		UUID id = summary.getNoteId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Note using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Notes
	 *
	 * @return 	List<Note>
	 */
    public List<Note> getAllNote() {
		List<Note> list = projector.findAll( new FindAllNoteQuery() );
		return list;
	}

